draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // lightning bolt
  ctx.beginPath();
  ctx.moveTo(W / 2, 0);
  ctx.lineTo(W / 2 + Math.sin(t) * 50, H / 2);
  ctx.lineTo(W / 2 - Math.sin(t) * 50, H);
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2 + Math.cos(t) * 100, 50, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W / 2 - Math.cos(t) * 100, 50, 30, 0, 2 * Math.PI);
  ctx.fill();

  // stick figure
  ctx.beginPath();
  ctx.arc(W / 2, H - 50, 20, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 30);
  ctx.lineTo(W / 2, H - 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 70);
  ctx.lineTo(W / 2 - 30, H - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 70);
  ctx.lineTo(W / 2 + 30, H - 50);
  ctx.stroke();

  ctx.restore();
}
